def getModuloOf(a, two):
    i=1;
    b = int(two[:i]);
    while(b<a and i<len(two)):
        i=i+1;
        b=int(two[:i]);
    if(b<a or i==len(two)):
        return b%a;
    else:
        rem=b%a;
        s=str(rem)+two[i:];
        return getModuloOf(a,s);

